{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([session("a", 1, True), session("b", 1, None),
                            session("c", 1, False)]) == 1 / 3
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_and_handles_empty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 1, False)] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (5, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_values_whitespace_and_skipped_lines():
    lines = ["  ", "  # comment,not,a,record", " a , 3 , 1 ",
             "b, -2, 0", " c, 4,   ", "# end"]
    assert parse_session_log(lines) == [session("a", 3, True),
                                        session("b", -2, False),
                                        session("c", 4, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1,yes"])
def test_parse_session_log_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log([" ", "# skip", line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts():
    earlier = session("a", 1, True)
    latest = session("a", 3, None)
    events = [earlier, session("z", 2, True), session("b", 2, False), latest]
    assert dedupe_sessions(events) == [events[2], events[1], latest]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_fills_gaps_and_respects_range():
    events = [session("a", 0, True), session("b", 1, True),
              session("c", 1, True), session("d", 2, None),
              session("e", 3, False), session("f", 4, True)]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 5, True), session("c", 5, False)],
              "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 4) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 4) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({"a": [session("a", 1, True), session("b", 5, False)]}, 2)["recent"] == 0


def test_top_converting_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_has_sorted_keys_and_none_for_empty():
    result = conversion_rate_by_group({"z": [], "b": [session("b", 1, None)],
                                       "a": [session("a", 1, True)]})
    assert list(result.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_conversion_streak_only_counts_consecutive_positive_values():
    assert longest_conversion_streak([1, 2, 0, 5, -1, 3, 4, 5]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
